@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Graphite — a soft, recessed dark UI built from a portfolio-widget reference.
 *
 * Design language (authored from the reference, not inherited from any sibling DS):
 *   - Warm-neutral monochrome greys that ASCEND in lightness as surfaces rise:
 *     page → recessed track → card → floating tile → hover → raised pill.
 *   - Tiles sit gently proud of the card: a 0.0625rem top white highlight + a soft
 *     bottom shadow. They are calm, never glassy or glowy.
 *   - Wells (segmented nav track, inputs, the card container itself) press IN:
 *     a top inset shadow makes them read as recessed into the surface.
 *   - The only "accent" is a brighter near-grey — the raised pill. No hue.
 *   - Soft white text (#E0E0E0), never pure white, so nothing glares on grey.
 *   - Hairline white borders (~7% white) keep edges crisp without lines reading.
 */

:root {
  /* ─── Surfaces (deepest → highest) ─── */
  --background: oklch(0.218 0 0);          /* #1A1A1A — page */
  --foreground: oklch(0.907 0 0);          /* #E0E0E0 — soft white */

  --card: oklch(0.301 0 0);                /* #2E2E2E — card container */
  --card-foreground: oklch(0.907 0 0);

  --popover: oklch(0.333 0 0);             /* #363636 — floating tile */
  --popover-foreground: oklch(0.907 0 0);

  /* ─── Primary: the raised pill, monochrome ─── */
  --primary: oklch(0.398 0 0);             /* #474747 — active pill */
  --primary-foreground: oklch(0.907 0 0);

  --secondary: oklch(0.269 0 0);           /* #262626 — recessed track */
  --secondary-foreground: oklch(0.798 0 0); /* #BDBDBD */

  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.683 0 0);    /* #999999 — dim label */

  --accent: oklch(0.36 0 0);               /* #3D3D3D — hover tile */
  --accent-foreground: oklch(0.907 0 0);

  --destructive: oklch(0.6 0.18 25);
  --destructive-foreground: oklch(0.96 0 0);
  --success: oklch(0.6 0.135 150);
  --success-foreground: oklch(0.218 0 0);
  --warning: oklch(0.74 0.135 75);
  --warning-foreground: oklch(0.218 0 0);

  --border: oklch(1 0 0 / 0.07);           /* hairline white */
  --input: oklch(0.269 0 0);               /* #262626 — recessed well */
  --ring: oklch(1 0 0 / 0.2);
  /*
   * Radius scale — generous, soft-rounded. Declared as literals in :root (not
   * just derived in @theme) so the showcase token-injector picks the whole
   * scale up and every rounded-* surface adopts it, not only rounded-lg.
   */
  --radius: 1.25rem;                       /* 1.25rem — base / rounded-lg */
  --radius-sm: 0.875rem;                   /* 0.875rem */
  --radius-md: 1.125rem;                   /* 1.125rem — cards, kbd, menu rows */
  --radius-lg: 1.25rem;                    /* 1.25rem — inputs, tiles */
  --radius-xl: 1.5rem;                     /* 1.5rem — large cards */
  --radius-2xl: 1.75rem;                   /* 1.75rem — container wells */

  /*
   * ─── Shadow scale ───
   * Raised surfaces go OUT (highlight on top, soft drop below); wells go IN
   * (dark top inset). All values are oklch — no rgba anywhere.
   */

  /* Raised tile — the default calm surface */
  --shadow-tile:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.05),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.18);

  /* Raised pill — the primary, slightly more lift */
  --shadow-pill:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.08),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.2),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.25);

  --shadow-pill-hover:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.1),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.28),
    0 0.25rem 0.625rem oklch(0 0 0 / 0.3);

  /* Raised scale — xs / sm / md / lg / xl */
  --shadow-xs:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.04),
    0 0.0625rem 0.0625rem oklch(0 0 0 / 0.2);

  --shadow-sm:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.05),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.22),
    0 0.0625rem 0.0625rem oklch(0 0 0 / 0.16);

  --shadow-md:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.06),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.28),
    0 0.25rem 0.625rem oklch(0 0 0 / 0.22);

  --shadow-lg:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.07),
    0 0.375rem 0.875rem oklch(0 0 0 / 0.34),
    0 0.75rem 1.75rem oklch(0 0 0 / 0.28);

  --shadow-xl:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.08),
    0 0.75rem 1.75rem oklch(0 0 0 / 0.42),
    0 1.5rem 3rem oklch(0 0 0 / 0.34);

  /* Recessed wells — dark top inset + faint bottom highlight */
  --shadow-inset:
    inset 0 0.0625rem 0.125rem oklch(0 0 0 / 0.28),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.03);

  --shadow-inset-deep:
    inset 0 0.125rem 0.25rem oklch(0 0 0 / 0.4),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.04);

  /* Card container — a wide, soft well the tiles sit inside */
  --shadow-well: inset 0 0.0625rem 0.125rem 0.125rem oklch(0 0 0 / 0.18);

  /* Pill gradient — gentle top→bottom on the raised primary */
  --pill-gradient: linear-gradient(180deg, oklch(0.42 0 0) 0%, oklch(0.37 0 0) 100%);
  --pill-gradient-hover: linear-gradient(180deg, oklch(0.45 0 0) 0%, oklch(0.4 0 0) 100%);

  /* Active label sinks into the pill */
  --text-shadow-pressed: 0 0.0625rem 0.0625rem oklch(0 0 0 / 0.4);

  /*
   * ─── Legacy aliases ───
   * The 80+ shadcn primitives reference --shadow-s/-m/-l and a few specialised
   * tokens. Mapped to the graphite recipe so each picks up the look untouched.
   */
  --shadow-s: var(--shadow-sm);
  --shadow-m: var(--shadow-md);
  --shadow-l: var(--shadow-lg);
  --shadow-button: var(--shadow-pill);
  --shadow-button-hover: var(--shadow-pill-hover);
  --shadow-primary: var(--shadow-pill);

  /*
   * ─── Chart palette ───
   * Monochrome, but BRIGHT: data marks must read as light on the dark card
   * (L ~0.30). The old ramp sat at the primary's L (~0.40), barely above the
   * card, so graphs washed out. These five shades all stay well above the
   * card and step down in clear, distinguishable increments.
   */
  --chart-1: oklch(0.86 0 0);
  --chart-2: oklch(0.74 0 0);
  --chart-3: oklch(0.62 0 0);
  --chart-4: oklch(0.5 0 0);
  --chart-5: oklch(0.94 0 0);

  /* --- Motion (soft profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 180ms;
  --transition-duration-base: 240ms;
  --transition-duration-slow: 300ms;
  --ease-out: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-in: cubic-bezier(0.895, 0.03, 0.685, 0.22);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: 0.875rem;
  --radius-md: 1.125rem;
  --radius-lg: 1.25rem;
  --radius-xl: 1.5rem;
  --radius-2xl: 1.75rem;

  --shadow-tile: var(--shadow-tile);
  --shadow-pill: var(--shadow-pill);
  --shadow-pill-hover: var(--shadow-pill-hover);
  --shadow-inset: var(--shadow-inset);
  --shadow-inset-deep: var(--shadow-inset-deep);
  --shadow-well: var(--shadow-well);
  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-family: ui-rounded, "SF Pro Rounded", "Hiragino Maru Gothic ProN", -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
    letter-spacing: -0.01em;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: spacious;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 62);
  --layout-inset: calc(var(--spacing, 0.25rem) * 10);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 12);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 6);
}

